begin;
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
create function pg_temp.reject(q text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then return;end;raise exception 'FAIL accepted: %',label;end $$;
grant execute on function pg_temp.check_true(boolean,text),pg_temp.reject(text,text) to authenticated,service_role,anon;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('cc190000-0000-4000-8000-000000000001','admin@example.invalid',now(),'{}'),('cc190000-0000-4000-8000-000000000002','recipient@example.invalid',now(),'{"registration_flow":"merchant_v1"}');
insert into public.admin_users(user_id,role) values('cc190000-0000-4000-8000-000000000001','owner');
select set_config('request.jwt.claims','{"sub":"cc190000-0000-4000-8000-000000000001","role":"authenticated","amr":[{"method":"password"}]}',true);
set local role authenticated;
select set_config('qa.invite',public.create_admin_merchant_invitation(jsonb_build_object('business_name','OTP Merchant','email','recipient@example.invalid','platform_account_id','acct_fixture','livemode',false,'token_sha256',repeat('a',64),'expires_at',clock_timestamp()+interval '1 day'))::text,true);
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','browser cannot call public-token preparation RPC directly');
select pg_temp.reject('select public.finish_merchant_invitation_code(gen_random_uuid(),gen_random_uuid(),''sent'')','browser cannot forge code send receipt');
select pg_temp.reject('select * from kma_internal.merchant_invitation_code_requests','browser cannot read code-send tracking');
reset role;set local role anon;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','anonymous database access cannot initiate code send');
reset role;set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''b'',64),gen_random_uuid(),''https://partners.example.invalid'')','unknown token is unavailable');
select pg_temp.reject('select public.prepare_merchant_invitation_code(''bad'',gen_random_uuid(),''https://partners.example.invalid'')','malformed token hash rejected');
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),null,''https://partners.example.invalid'')','request identity required');
select set_config('qa.first',public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000010','https://partners.example.invalid')::text,true);
select pg_temp.check_true((current_setting('qa.first')::jsonb->>'send')::boolean and current_setting('qa.first')::jsonb->>'email'='recipient@example.invalid','only stored recipient is returned for first dispatch');
select pg_temp.check_true(not(public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000010','https://partners.example.invalid')->>'send')::boolean,'same request does not send twice');
select pg_temp.check_true(not(public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000011','https://partners.example.invalid')->>'send')::boolean,'new request during cooldown does not send');
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),''cc190000-0000-4000-8000-000000000010'',''https://other.example.invalid'')','request replay cannot change recipient portal');
select pg_temp.reject('select public.finish_merchant_invitation_code(''cc190000-0000-4000-8000-000000000010'',gen_random_uuid(),''sent'')','wrong dispatch lease cannot forge acceptance');
select pg_temp.reject('select public.finish_merchant_invitation_code(''cc190000-0000-4000-8000-000000000010'',(current_setting(''qa.first'')::jsonb->>''lease_id'')::uuid,''connected'')','code receipt cannot accept unrelated lifecycle states');
select public.finish_merchant_invitation_code('cc190000-0000-4000-8000-000000000010',(current_setting('qa.first')::jsonb->>'lease_id')::uuid,'sent');
select pg_temp.check_true(public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000010','https://partners.example.invalid')->>'status'='sent','same accepted request replays accepted status');
reset role;
update kma_internal.merchant_invitation_code_requests set retry_at=clock_timestamp()-interval '1 second';
set local role service_role;
select pg_temp.check_true(not(public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000010','https://partners.example.invalid')->>'send')::boolean,'accepted request never re-sends after cooldown');
select pg_temp.check_true(not(public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000011','https://partners.example.invalid')->>'send')::boolean,'blocked browser retry also stays idempotent');
select set_config('qa.second',public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000012','https://partners.example.invalid')::text,true);
select pg_temp.check_true((current_setting('qa.second')::jsonb->>'send')::boolean,'explicit new request after cooldown can send a fresh code');
reset role;
update kma_internal.merchant_invitation_code_requests set lease_expires_at=clock_timestamp()-interval '1 second',retry_at=clock_timestamp()-interval '1 second' where request_id='cc190000-0000-4000-8000-000000000012';
set local role service_role;
select set_config('qa.lost',public.prepare_merchant_invitation_code(repeat('a',64),'cc190000-0000-4000-8000-000000000012','https://partners.example.invalid')::text,true);
select pg_temp.check_true(current_setting('qa.lost')::jsonb->>'status'='unknown' and not(current_setting('qa.lost')::jsonb->>'send')::boolean,'lost response stays unknown without unsafe Auth resend');
reset role;
insert into kma_internal.merchant_invitation_code_requests(request_id,invitation_id,recipient,recipient_origin,status,send_started,retry_at,lease_expires_at)
select gen_random_uuid(),(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid,'recipient@example.invalid','https://partners.example.invalid','sent',true,clock_timestamp()-interval '1 second',clock_timestamp()-interval '1 second' from generate_series(1,3);
set local role service_role;
select set_config('qa.capped',public.prepare_merchant_invitation_code(repeat('a',64),gen_random_uuid(),'https://partners.example.invalid')::text,true);
select pg_temp.check_true(current_setting('qa.capped')::jsonb->>'status'='cooldown' and not(current_setting('qa.capped')::jsonb->>'send')::boolean and (current_setting('qa.capped')::jsonb->>'retry_at')::timestamptz>clock_timestamp()+interval '59 minutes','five sends per recipient per hour is enforced');
reset role;
select pg_temp.check_true((select count(*)=5 from kma_internal.merchant_invitation_code_requests where send_started),'duplicate/reload/cooldown never count as actual dispatch');
select pg_temp.check_true((select count(*)=2 from auth.users),'preparing codes did not create or authenticate any user');
select pg_temp.check_true(not exists(select 1 from public.admin_users where user_id='cc190000-0000-4000-8000-000000000002') and not exists(select 1 from public.affiliate_users where user_id='cc190000-0000-4000-8000-000000000002'),'merchant signup metadata creates no admin or creator membership');
update public.merchant_invitations set claimed_by='cc190000-0000-4000-8000-000000000002' where id=(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid;
update auth.users set email='changed@example.invalid' where id='cc190000-0000-4000-8000-000000000002';
set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','claimed identity with changed email cannot initiate code send');
reset role;
update public.merchant_invitations set claimed_by=null,expires_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid;
set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','expired invitation cannot send code');
reset role;
update public.merchant_invitations set expires_at=clock_timestamp()+interval '1 day',revoked_at=clock_timestamp() where id=(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid;
set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','revoked invitation cannot send code');
reset role;
update public.merchant_invitations set revoked_at=null,confirmed_at=clock_timestamp() where id=(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid;
set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','confirmed invitation cannot send code');
reset role;
update public.merchant_invitations set confirmed_at=null where id=(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid;
update public.merchant_connections set status='revoked' where merchant_id=(current_setting('qa.invite')::jsonb->>'merchant_id')::uuid;
set local role service_role;
select pg_temp.reject('select public.prepare_merchant_invitation_code(repeat(''a'',64),gen_random_uuid(),''https://partners.example.invalid'')','revoked connection cannot send code');
reset role;
select pg_temp.check_true(not has_function_privilege('anon','public.prepare_merchant_invitation_code(text,uuid,text)','EXECUTE') and not has_function_privilege('authenticated','public.prepare_merchant_invitation_code(text,uuid,text)','EXECUTE') and has_function_privilege('service_role','public.prepare_merchant_invitation_code(text,uuid,text)','EXECUTE'),'only validated Edge service can prepare OTP dispatch');
select pg_temp.check_true(not has_function_privilege('authenticated','public.finish_merchant_invitation_code(uuid,uuid,text)','EXECUTE') and has_function_privilege('service_role','public.finish_merchant_invitation_code(uuid,uuid,text)','EXECUTE'),'only service can record OTP send outcomes');
rollback;
